package com.starlight.greetings.web; import com.starlight.greetings.application.*; import jakarta.servlet.http.HttpServletRequest; import java.util.Map; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class SurveyMetricsController {private final SurveyMetricsService service;private final SessionService sessions;public SurveyMetricsController(SurveyMetricsService service,SessionService sessions){this.service=service;this.sessions=sessions;}@GetMapping("/survey") public ApiEnvelope<Map<String,Object>> survey(){return ApiEnvelope.of(service.survey());}@PostMapping("/events") public ResponseEntity<ApiEnvelope<Map<String,Object>>> event(@RequestBody Map<String,Object> input,HttpServletRequest req){return ResponseEntity.status(201).body(ApiEnvelope.of(service.event(input,viewer(req))));} private String viewer(HttpServletRequest req){try{var view=sessions.current(SessionCookie.token(req));return "member".equals(view.role())?"member":null;}catch(Exception e){return "guest";}}@PostMapping("/events/survey-open") public ResponseEntity<ApiEnvelope<Map<String,Object>>> open(@RequestBody Map<String,Object> input,HttpServletRequest req){return ResponseEntity.status(201).body(ApiEnvelope.of(service.surveyOpen(input)));}@GetMapping("/admin/survey") public ApiEnvelope<Map<String,Object>> settings(@RequestHeader(value="x-csrf-token",required=false)String csrf,HttpServletRequest req){sessions.adminRead(SessionCookie.token(req));return ApiEnvelope.of(service.settings());}@PutMapping("/admin/survey") public ApiEnvelope<Map<String,Object>> configure(@RequestBody Map<String,Object> input,@RequestHeader(value="x-csrf-token",required=false)String csrf,HttpServletRequest req){var user=sessions.admin(SessionCookie.token(req),csrf);return ApiEnvelope.of(service.configure(input,user.id()));}@GetMapping("/admin/metrics") public ApiEnvelope<Map<String,Object>> metrics(@RequestParam(required=false)String from,@RequestParam(required=false)String to,@RequestHeader(value="x-csrf-token",required=false)String csrf,HttpServletRequest req){sessions.adminRead(SessionCookie.token(req));return ApiEnvelope.of(service.summary(from,to));}}
